        fs.writeFileSync(ARQ_RELAÇOES, JSON.stringify(relacionamentos, null, 2));
    }
} else {
    // Arquivo ainda não existe: cria vazio e já carrega na variável
    fs.writeFileSync(ARQ_RELAÇOES, JSON.stringify({ casamentos: [], namoros: [] }, null, 2));
    relacionamentos = { casamentos: [], namoros: [] };
}

// Dados vindos do Akinator (a estrutura depende do seu arquivo)
let akiData = fs.existsSync(ARQ_AKINATOR)
