const jogos = {
    'LEPRECHAUN RICHES': { min: 0.93, media: 3.59, max: 7.91, chance: 38 },
    // ... adicione os demais jogos aqui
};


// ---------------------------------------------------------------------------
// 3) CONSTANTES E FUNÇÕES AUXILIARES
// ---------------------------------------------------------------------------

const CABECALHO = '🍀 *PORCENTAGENS E ESTATÍSTICAS* 💰\n\n';
const RODAPE = '\n\nObservação: As porcentagens podem conter alguma divergência...';

/** Monta uma linha no formato "• R$ valor,xx". */
function linhaValor(label, valor) {
    return `• ${label}: R$ ${valor.toFixed(2)}`;
}

/**
 * Aplica variação aleatória de ±10% em min / media / max
 * e altera a chance entre −5 e +4 pontos (limitada a [1, 100]).
 */
function atualizarValores({ min, media, max, chance }) {
    const fator = 1 + Math.random() * 0.2 - 0.1;

    return {
        min: min * fator,
        media: media * fator,
        max: max * fator,
        chance: Math.max(1, Math.min(100, chance + Math.floor(Math.random() * 10 - 5)))
    };
}

/** Monta o corpo das estatísticas de um jogo (sem o rodapé). */
function blocoEstatisticas(titulo, dados) {
    const { min, media, max, chance } = atualizarValores(dados);

    return `${CABECALHO}${titulo}\n${[
        linhaValor('Mínimo', min),
        linhaValor('Média', media),
        linhaValor('Máximo', max),
        `• Chance: ${chance}%`
    ].join('\n')}`;
}


// ---------------------------------------------------------------------------
// 4) FUNÇÃO PRINCIPAL
// ---------------------------------------------------------------------------

function responderJogo(jogo) {
    // ---------------------------------------------------------------
    // Modo "todos" os jogos
    // ---------------------------------------------------------------
    if (jogo === 'all') {
        const blocos = [];

        for (const [nome, dados] of Object.entries(jogos)) {
            blocos.push(blocoEstatisticas(`❲${nome}❳`, dados));
        }

        // Agora o rodapé aparece UMA vez (antes havia um por bloco)
        return blocos.join('\n\n') + RODAPE;
    }

    // ---------------------------------------------------------------
    // Um jogo específico
    // ---------------------------------------------------------------
    const dados = jogos[jogo];

    if (!dados) {
        return `❌ Jogo "${jogo}" não encontrado.`;
    }

    const stats = atualizarValores(dados);
    return blocoEstatisticas(`❲${jogo}❳`, stats) + RODAPE;
}


// ============================================================
// USO: basta invocar no ponto de entrada da sua aplicação:
//
// responderJogo('all');           // estatísticas de todos os jogos
// responderJogo('LEPRECHAUN RICHES');
// ============================================================
```

**Principais melhorias:**

1. **Sintaxe corrigida** — o objeto de jogos estava "cortado" (faltava o `const jogos = {` e o fechamento `};`). Completei com o exemplo do próprio trecho.
2. **Separação por responsabilidades** — carga de arquivos, utilitários e lógica de resposta ficaram em blocos distintos, com comentários explicativos.
3. **DRY** — repetições de cabeçalho/rodapé viraram constantes, e o layout de valores saiu para funções próprias (`linhaValor` e `blocoEstatisticas`).
4. **Iteração mais limpa** — `Object.entries(jogos)` em vez de `Object.keys` + desestruturação manual a cada rodada.
5. **Robustez** — `try/catch` no parse do JSON e validação das chaves obrigatórias: se o arquivo estiver corrompido ou incompleto, ele salva um estado vazio seguro em vez de quebrar.
6. **Rodapé único no modo "todos"** — antes a mensagem de observação aparecia dentro de cada bloco (e repetida); agora aparece uma única vez no final.
7. **Funções posicionadas perto do uso** e documentadas, facilitando leitura futura e testes unitários.

Se quiser, posso também transformar isso numa estrutura modular (ex.: exportar as funções para reuso) ou sugerir o preenchimento do `jogosAkinator` a partir do `aki.json`.

