const CABECALHO = '🍀 *PORCENTAGENS E ESTATÍSTICAS* 💰\n\n';
const RODAPE = '\n\nObservação: As porcentagens podem conter alguma divergência...';

/** Converte um valor em linha de lista no formato "*R$ x,xx*". */
function linhaValor(label, valor) {
    return `• ${label}: R$ ${valor.toFixed(2)}`;
}

/**
 * Aplica variação aleatória de ±10% nos valores e muda a chance em até ±4,
 * sempre respeitando o intervalo [1, 100].
 */
function atualizarValores({ min, media, max, chance }) {
    const fator = 1 + Math.random() * 0.2 - 0.1;

    return {
        min: min * fator,
        media: media * fator,
        max: max * fator,
        chance: Math.max(1, Math.min(100, chance + Math.floor(Math.random() * 10 - 5)))
    };
}

/** Monta o corpo das estatísticas (sem o rodapé), usando os valores atualizados. */
function blocoEstatisticas(titulo, dados) {
    const { min, media, max, chance } = atualizarValores(dados);

    return `${CABECALHO}${titulo}\n${[
        linhaValor('Mínimo', min),
        linhaValor('Média', media),
        linhaValor('Máximo', max),
        `• Chance: ${chance}%`
    ].join('\n')}`;
}


